CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users(id BIGSERIAL PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('ADMIN','DOCTOR','RECEPTIONIST','PATIENT')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE auth_tokens(id BIGSERIAL PRIMARY KEY,token_hash VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX auth_tokens_user_idx ON auth_tokens(user_id);
CREATE TABLE doctors(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES users(id),license_number VARCHAR(40) NOT NULL UNIQUE,specialty VARCHAR(120) NOT NULL,slot_minutes INTEGER NOT NULL CHECK(slot_minutes BETWEEN 10 AND 240),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX doctors_specialty_idx ON doctors(specialty);
CREATE TABLE patients(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES users(id),medical_record_number VARCHAR(30) NOT NULL UNIQUE,date_of_birth DATE NOT NULL,phone VARCHAR(30),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE appointments(id BIGSERIAL PRIMARY KEY,doctor_id BIGINT NOT NULL REFERENCES doctors(id),patient_id BIGINT NOT NULL REFERENCES patients(id),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN('SCHEDULED','COMPLETED','CANCELLED')),diagnosis VARCHAR(1000),treatment VARCHAR(2000),created_by BIGINT NOT NULL REFERENCES users(id),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(ends_at>starts_at));CREATE INDEX appointments_doctor_start_idx ON appointments(doctor_id,starts_at);CREATE INDEX appointments_patient_idx ON appointments(patient_id);ALTER TABLE appointments ADD CONSTRAINT appointments_no_overlap EXCLUDE USING gist(doctor_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status='SCHEDULED');

